def find_minimum_i(n, k, A0):
    def p(x):
        y = [0] * (len(x) + 1)
        for i in range(1, len(x) + 1):
            y[i] = y[i - 1] + x[i - 1]
        return y

    def contains_large_number(A, k):
        return any(x >= k for x in A)

    def calculate_Ai(A_prev):
        A_prev = [x - 1 for x in A_prev]
        return p(A_prev)

    # Initial check for A^0
    if contains_large_number(A0, k):
        return 0

    # Binary search for the minimum i
    low, high = 0, 1
    A_current = A0

    while True:
        A_next = calculate_Ai(A_current)
        if contains_large_number(A_next, k):
            high = low + (high - low) // 2
        else:
            low = high
            high *= 2
        A_current = A_next

        if low >= high:
            break

    # Final check for the found i
    A_current = A0
    for i in range(low + 1):
        A_current = calculate_Ai(A_current)
        if contains_large_number(A_current, k):
            return i

    return -1  # This should never be reached

